def table(rows,keys,labels=None):
    if not rows:return '无对应行。\n'
    def value(x):
        if isinstance(x,float):return f'{x:.4f}'
        return str(x)
    return '| '+' | '.join(labels or keys)+' |\n| '+' | '.join(['---']*len(keys))+' |\n'+'\n'.join('| '+' | '.join(value(r.get(k,'')) for k in keys)+' |' for r in rows)+'\n'
def point(ds,w,K,L,m):return next(x for x in P if x['dataset']==ds and x['window']==w and int(x['K'])==K and int(x['L'])==L and x['method']==m)
def diag(ds,w,K,L):return next(x for x in M if x['dataset']==ds and x['window']==w and int(x['K'])==K and int(x['L'])==L and x['method']=='DIAGNOSIS')
brief=[]
for ds in DS:
    pp=[x for x in P if x['dataset']==ds and x['method'] in NAV];ss=[x for x in S if x['dataset']==ds];dd=[diag(ds,w,100,200) for w in ['A','B']];mis=sum(f(x['missing']) for x in dd)
    brief.append(dict(dataset=ds,navigation_points=len(pp),points_positive_vs_B32=sum(f(x['gain_vs_B32_pp'])>0 for x in pp),points_existing_covered=sum(bool(x['existing_covers']) for x in pp),configurations=len(ss),both_windows_not_existing_covered=sum(x['both_not_existing_covered']=='True' for x in ss),both_positive_and_not_existing_covered=sum(x['both_not_existing_covered']=='True' and x['both_positive_net']=='True' for x in ss),K100_L200_missing=int(mis),evaluated_missing_pct=100*sum(f(x['missing_evaluated']) for x in dd)/mis if mis else 0,frontier_adjacent_missing_pct=100*sum(f(x['missing_frontier_adjacent']) for x in dd)/mis if mis else 0,SQ_pool_coverage_pct=100*sum(f(x['SQ_pool_missing']) for x in dd)/mis if mis else 0,SQ_shortlist_retention_pct=100*sum(f(x['SQ_short_missing']) for x in dd)/sum(f(x['SQ_scan_missing']) for x in dd) if sum(f(x['SQ_scan_missing']) for x in dd) else 0))
csvwrite(R/'analysis/dataset_summary.csv',brief)
receipts=[read(p) for p in (R/'reviews').glob('*.receipt.json')];formal=[x for x in receipts if x['returncode']==0 and any('/configs/' in a and (a.endswith('.A.json') or a.endswith('.B.json')) for a in x['argv'])]
walls=sum(v['wall_seconds'] for ds in DS for w in ['A','B'] for x in read(R/'storage/results'/ds/w/'performance_complete.json')['results'] for v in x['rounds'])
diagsec=sum(read(R/'storage/results'/ds/w/'diagnosis_complete.json')['seconds'] for ds in DS for w in ['A','B']);oracle=sum(read(p)['seconds'] for p in (R/'storage/results').glob('*/*/k*/*/oracle.json') if 'seconds' in read(p));meta=sum(read(p)['seconds'] for p in (R/'storage/meta').glob('*/complete.json'))
dump(R/'analysis/cost_ledger.json',dict(formal_process_seconds_including_load_warmup_performance_oracles_and_diagnosis=sum(x['seconds'] for x in formal),formal_batch_wall_seconds=walls,mechanism_diagnosis_seconds=diagsec,auxiliary_oracle_seconds=oracle,static_graph_preprocessing_seconds=meta,qualification_and_legacy_success_seconds=sum(x['seconds'] for x in receipts if x['returncode']==0 and x not in formal),failed_process_receipts=[x for x in receipts if x['returncode']!=0],failed_process_recorded_seconds=sum(x['seconds'] for x in receipts if x['returncode']!=0),failed_build_attempt=read(R/'reviews/build_attempt1.json'),source_chain=read(R/'analysis/source_chain_receipt.json'),geometry=read(R/'analysis/geometry_receipt.json'),stdlib_audit=read(R/'analysis/stdlib_audit.json'),process_observations=read(R/'reviews/live_process_observations.json'),resource_revision=read(R/'resource_revision.json'),nested_costs_do_not_add=True,build=read(R/'reviews/build.json'),analysis=read(R/'analysis/analysis_receipt.json')))
text=['# E195 七数据集残差来源与导航增量详细定位','2026-11-01。固定七集、两个曝光公共查询窗口、真实K1/K100，1260正式点/3780完整T1批次完成。新资格140点，旧二进制控制56点（42个对应包逐字节比较）。默认E99 GT10保持。','## 本轮能回答的问题','本轮同时观察原主搜索轨迹、固定ID直接补全、SQ覆盖链和六个可部署辅助导航动作。所有导航保留完整B32候选C，再附加入口/代表选择与有界扩展。它是本轮独立辅助搜索，不是原API的暂停续搜。没有训练新门、修改主图或生成新GT。','主要汇总如下。“已有方法覆盖”要求同数据/窗口/K下至少相同严格GT-ID命中数且完整中位QPS不低，至少一项严格更好。已有方法含GT10、B32、OPT-B32和SQ；未覆盖仅指本轮离散网格。A/B两个窗口均未覆盖且同L相对B32净增益为正，仍是探索观察，不自动成为默认替换或统计显著证据。',table(brief,['dataset','points_positive_vs_B32','points_existing_covered','navigation_points','both_positive_and_not_existing_covered','frontier_adjacent_missing_pct','SQ_pool_coverage_pct'],['数据集','导航点同L增益为正','被已有方法覆盖点','导航点总数','两窗正且未覆盖配置','L200遗漏边界邻接%','SQ池覆盖%']),'## 范围、控制和证据身份','每集由固定PCG64随机排列抽取前1024条曝光公共query，拆为A/B各512条；GIST全部1000条拆为500/500。A/B源行不重叠，未额外保证逐向量或语义独立；它们不是全历史盲确认或新图复现。B32使用原16K监督表，SQ块表使用原前12K，不能把两者差异当纯评分因果。每个数据/窗口/K有GT10/B32共同11档L，SQ四档、OPT-B32一档、六种导航三档。所有具体配置在结果前固定。','ONEHOP96沿三行query-best seed一跳；DIST96/384用相同seed独立多步扩展；NOVEL96/384从query距离前12个C中按相对主visited及已选邻居的新覆盖选最多3个seed；REP384从真实h→C入邻居的静态代表中按query距离选seed。代表新增评分计入384预算，直接C评分另计。静态代表由有效出度、入度、ID决定，无GT监督。它们是明确基线而非导航价值最优估计。','辅助队列的边界：已选seed可主动展开；后续遇到原main visited、全部C和本动作已评分节点时，跳过精算并不再新入队。未选C不会因再次遇到而展开。离线边界机会不保证本动作实际能利用；这里未测试全评分缓存、恢复淘汰节点或其他状态共享。详见[实现边界](implementation_boundary.md)。', '## 来源链与费用判定','旧全量固定ID源链取E184（七集、固定家族、L200、全56K查询），旧块链取E191全部原query。原件及数值未改，副本带historical前缀。新增两个窗口的SQ池→扫描→短名单→返回链由真实同窗主搜索重建，全量和本轮实际SQ救回对齐。源外、路由损失、容量损失、量化保留和最终合并是不同阶段；只有相同候选源不包含目标时，改池内评分才受到对应固定支持上限。','K100失败严格为单query命中0–9个，恰好10排除。总体成员增益、查询改善、脱离低召回和完整恢复不能互换。所有点保留实际成员损伤；保留C不保证最终GT成员无损。','## 分数据集结果']
for ds in DS:
    text+=['### '+names[ds]]
    bb=next(x for x in brief if x['dataset']==ds)
    text.append(f"本集72个导航点中，{bb['points_positive_vs_B32']}个同L相对B32净Recall为正，{bb['points_existing_covered']}个被已有方法覆盖；36个方法/K/L配置中，{bb['both_positive_and_not_existing_covered']}个在两窗都正且未被本轮已有网格覆盖。小计数、费用三轮范围和强控制的质量差需一并看。")
    rows=[]
    for w in ['A','B']:
        for K in [1,100]:
            d=diag(ds,w,K,200);missing=f(d['missing']);rows.append(dict(window=w,K=K,missing=int(missing),evaluated=int(f(d['missing_evaluated'])),frontier=int(f(d['missing_frontier_adjacent'])),noedge=int(f(d['missing_no_frontier_edge'])),zero=int(f(d['missing_zero_indegree'])),C=int(f(d['C_missing'])),SQ_pool=int(f(d['SQ_pool_missing'])),SQ_scan=int(f(d['SQ_scan_missing'])),SQ_short=int(f(d['SQ_short_missing'])),SQ_final=int(f(d['SQ_rescued']))))
    text.append(table(rows,['window','K','missing','evaluated','frontier','noedge','zero','C','SQ_pool','SQ_scan','SQ_short','SQ_final'],['窗','K','遗漏','已评分未返','未评但邻接边界','无该一步边','零入度','直接C覆盖','SQ池','SQ扫描','SQ短单','SQ救回']))
    text.append('同L200完整性能（召回为百分数；gain为相对B32的百分点；QPS包括正常输出生命周期、选择和全部附加动作）：')
    rr=[]
    for w in ['A','B']:
        for K in [1,100]:
            for m in ['GT10','B32','REUSE-SQ',*NAV]:
                a=point(ds,w,K,200,m);rr.append(dict(window=w,K=K,method=m,recall=f(a['recall_pct']),QPS=f(a['qps']),us=f(a['mean_us']),gain_B32=f(a['gain_vs_B32_pp']),rescue_B32=a['rescued_vs_B32'],loss_B32=a['lost_vs_B32'],B32_covers=a['B32_covers'],GT_covers=a['GT_covers']))
    text.append(table(rr,['window','K','method','recall','QPS','us','gain_B32','rescue_B32','loss_B32','B32_covers','GT_covers']))
    # Display every two-window opportunity; if absent, retain the highest observed same-cost delta as a bounded diagnostic example.
    retained=[x for x in S if x['dataset']==ds and x['both_positive_net']=='True' and x['both_not_existing_covered']=='True']
    text.append('两窗均正且未被已有网格覆盖的配置：'+ ('、'.join(f"{x['method']}/K{x['K']}/L{x['L']}" for x in retained) if retained else '本轮没有。'))
    text.append(f"结构口径：K100/L200两窗合计遗漏中，已评分未返回占{bb['evaluated_missing_pct']:.3f}%，来自已评分未展开边界的一步邻接机会占{bb['frontier_adjacent_missing_pct']:.3f}%；SQ候选池覆盖{bb['SQ_pool_coverage_pct']:.3f}%，扫描内遗漏的短名单保留为{bb['SQ_shortlist_retention_pct']:.3f}%。边界指曾评分但未展开的集合，包含被拒绝或淘汰节点，并非终止beam的pending队列。一步邻接机会不等于实际beam可达或可支付救回；无一步边也不等于全图不可达。")
    text.append(f"[完整曲线](analysis/{ds}_recall_qps.svg)；全部L、逐query增量、置信区间、尾部和覆盖见points.csv/query_hits.npz。")
text+=['## 入度、出度、未访问邻居能否解释导航','原主搜索的局部记录实现逐query核对ID和距离字节；所有来自已展开节点的合法出邻居均已被评分，不变量违例为0。已评分而严格GT-ID未返回可涉及近并列或重复向量，不能统一叫导航失效，也未修改GT消除损伤。','C节点统计按query出现次数加权，非全局distinct节点。正确C与非正确C、C与GT的度数差异是描述，不是密度/连通性唯一因果。没有将图的分配槽数当有效出度，也没有用原IP下的余弦密度代替任务metric。','单seed诊断每窗/每K取L200前64条固定窗口query、最多6个query-best C，逐个支付相同384额外精算上限，比较对直接B32的真实新增/损失成员。此probe用于事后分析；其单seed收益并集不是联合多入口搜索收益。相关的方向、样本数和A/B一致性见下表；常数特征或常数收益的相关记空，不补零。',table(A,['dataset','window','K','feature','seed_probes','positive_probes','negative_probes','spearman','within_query_centered_pearson']),'## 成本、实现核验与限制','全部正式查询在CPU15、实际一线程，OMP/BLAS/MKL/NUMEXPR均1，单方法串行。完整计时包含正常Batch分配/初始化、路由、原主搜索、直接补点、代表评分/选择、扩展、合并、六数组复制与销毁。每点三轮方法轮转，三轮输出和工作量相同；不把QPS范围当置信区间。','每个导航点的所有query同时通过原生线性合并oracle及Python/NumPy全排序第二实现，核最终ID/距离字节、唯一性和全部候选事件。原GT10/B32/SQ与旧二进制资格包SHA对齐。第二实现由同一执行者完成，不称独立人员复现。原始四数组与三轮六数组SHA、候选事件、工作量、原生oracle和诊断收据都保留。','所有阶段微计时仅来自wall外的oracle重放，不能相加冒充正式完整wall或将其占比直接移植。REP的离线全图统计/映射、图加载、资格、失败尝试和已有训练债分别记账；无新训练不清零旧成本。', '候选事件的无损证据比初始估计大，运行中仅将本轮/root新增存储额度从1GiB修订为1.5GiB，并保留300MiB空闲；科学矩阵/模型/角色/预算不变，未删除旧文件，详见[资源修订](resource_revision.json)。费用账见[cost_ledger.json](analysis/cost_ledger.json)，全图静态预处理在storage/meta；正式进程总wall包含加载/预热/原生核验/详细诊断，正式batch wall、oracle、诊断是其中嵌套项，不相加。','单图/画像、曝光公共测试、固定两个窗口、离散预算、K1稀少事件、导航代表基线并非所有政策、未验证修图与新评分器，限制均保留。对当前候选池或动作的失败不外推成所有残差/所有数据集无效。E173/E191/E194历史正面证据保留各自费用与身份。','## 证据索引','[固定协议](protocol.md) · [正式冻结](formal_freeze.json) · [状态](state.json) · [1260点](analysis/points.csv) · [机制与阶段归因](analysis/mechanisms.csv) · [两窗一致性](analysis/stability.csv) · [逐query命中](analysis/query_hits.npz) · [单seed](analysis/single_seed.csv) · [第二实现核验](analysis/analysis_receipt.json)']
text += ['## 补充几何定位', '背景r8是原坐标欧氏距离到固定8192背景点的第8近半径，排除自身。raw-IP数据只作背景邻近度代理，不等于原任务密度；不改变在线排序。样本角色与GT均事后，不提供因果/线上规则。', table(list(csv.DictReader((R/'analysis/geometry_role_summary.csv').open())), ['dataset','window','role','incidences','unique_nodes','mean_r8','median_r8','mean_norm']), '与既定单seed实际增量的相关；无定义保留空值：', table(list(csv.DictReader((R/'analysis/geometry_seed_associations.csv').open())), ['dataset','window','K','feature','probes','spearman','within_query_centered_pearson']), '[几何协议](geometry_protocol.md) · [几何核验与耗时](analysis/geometry_receipt.json) · [stdlib全量整数/hash/wall核验](analysis/stdlib_audit.json)']
